from itertools import permutations

def solve_logic_puzzle():
    people = ['Casey', 'Emery', 'Morgan', 'Parker', 'Sawyer']
    colors = ['blue', 'orange', 'red', 'white', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
    drinks = ['cocoa', 'juice', 'milk', 'tea', 'water']
    hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

    def is_valid_solution(assignment):
        # assignment[i] = (person, color, pet, drink, hobby) for house i (0-indexed)

        # Build lookup dictionaries
        house_person = {i: assignment[i][0] for i in range(5)}
        house_color = {i: assignment[i][1] for i in range(5)}
        house_pet = {i: assignment[i][2] for i in range(5)}
        house_drink = {i: assignment[i][3] for i in range(5)}
        house_hobby = {i: assignment[i][4] for i in range(5)}

        # 1. Fencing → Milk
        for i in range(5):
            if house_hobby[i] == 'fencing' and house_drink[i] != 'milk':
                return False
            if house_drink[i] == 'milk' and house_hobby[i] != 'fencing':
                return False

        # 2. Casey next to Blue house
        casey_h = None
        blue_h = None
        for i in range(5):
            if house_person[i] == 'Casey':
                casey_h = i
            if house_color[i] == 'blue':
                blue_h = i
        if abs(casey_h - blue_h) != 1:
            return False

        # 3. Sawyer → Horse
        for i in range(5):
            if house_person[i] == 'Sawyer' and house_pet[i] != 'horse':
                return False
            if house_pet[i] == 'horse' and house_person[i] != 'Sawyer':
                return False

        # 4. White → Chess
        for i in range(5):
            if house_color[i] == 'white' and house_hobby[i] != 'chess':
                return False
            if house_hobby[i] == 'chess' and house_color[i] != 'white':
                return False

        # 5. Red → Fish
        for i in range(5):
            if house_color[i] == 'red' and house_pet[i] != 'fish':
                return False
            if house_pet[i] == 'fish' and house_color[i] != 'red':
                return False

        # 6. Hiking person ≠ Casey
        for i in range(5):
            if house_hobby[i] == 'hiking' and house_person[i] == 'Casey':
                return False

        # 7. Red → Fencing
        for i in range(5):
            if house_color[i] == 'red' and house_hobby[i] != 'fencing':
                return False
            if house_hobby[i] == 'fencing' and house_color[i] != 'red':
                return False

        # 8. Blue → Juice
        for i in range(5):
            if house_color[i] == 'blue' and house_drink[i] != 'juice':
                return False
            if house_drink[i] == 'juice' and house_color[i] != 'blue':
                return False

        # 9. Emery immediately left of Yellow house
        emery_h = None
        yellow_h = None
        for i in range(5):
            if house_person[i] == 'Emery':
                emery_h = i
            if house_color[i] == 'yellow':
                yellow_h = i
        if yellow_h != emery_h + 1:
            return False

        # 10. Parker → Dog
        for i in range(5):
            if house_person[i] == 'Parker' and house_pet[i] != 'dog':
                return False
            if house_pet[i] == 'dog' and house_person[i] != 'Parker':
                return False

        # 11. Morgan immediately left of Tea drinker
        morgan_h = None
        tea_h = None
        for i in range(5):
            if house_person[i] == 'Morgan':
                morgan_h = i
            if house_drink[i] == 'tea':
                tea_h = i
        if tea_h != morgan_h + 1:
            return False

        # 12. Painting person next to Morgan
        morgan_h = None
        painting_h = None
        for i in range(5):
            if house_person[i] == 'Morgan':
                morgan_h = i
            if house_hobby[i] == 'painting':
                painting_h = i
        if abs(painting_h - morgan_h) != 1:
            return False

        # 13. Casey immediately left of Cocoa drinker
        casey_h = None
        cocoa_h = None
        for i in range(5):
            if house_person[i] == 'Casey':
                casey_h = i
            if house_drink[i] == 'cocoa':
                cocoa_h = i
        if cocoa_h != casey_h + 1:
            return False

        # 14. Hiking person immediately left of dog owner (Parker)
        hiking_h = None
        parker_h = None
        for i in range(5):
            if house_hobby[i] == 'hiking':
                hiking_h = i
            if house_person[i] == 'Parker':
                parker_h = i
        if parker_h != hiking_h + 1:
            return False

        # 15. Bird owner immediately left of Orange house
        bird_h = None
        orange_h = None
        for i in range(5):
            if house_pet[i] == 'bird':
                bird_h = i
            if house_color[i] == 'orange':
                orange_h = i
        if orange_h != bird_h + 1:
            return False

        return True

    # Try all permutations
    for p_perm in permutations(people):
        for c_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for d_perm in permutations(drinks):
                    for h_perm in permutations(hobbies):
                        assignment = [(p_perm[i], c_perm[i], pet_perm[i], d_perm[i], h_perm[i]) for i in range(5)]
                        if is_valid_solution(assignment):
                            return assignment

    return None

solution = solve_logic_puzzle()

if solution:
    for i in range(5):
        if solution[i][1] == 'blue':
            print(f"ANSWER: {solution[i][0]}")
else:
    print("No solution found")
